from pathlib import Path
import os,json,hashlib,gc
assert os.environ.get('MICRODUCK_BOUNDED_CAD')=='1'
import numpy as np,trimesh as tm,manifold3d as mf
D=Path(__file__).resolve().parent;r=json.loads((D/'check.json').read_text());am=D.parent/'amp-mounts/amp-mount-fragment.json';mount=json.loads(am.read_text());rows=json.loads(Path(r['sourceManifest']).read_text())['parts']
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def load(q):
 assert sha(q['file'])==q['sha256'];m=tm.load(q['file'],force='mesh');m.apply_transform(q.get('worldTransform',np.eye(4)));s=mf.Manifold(mf.Mesh64(np.array(m.vertices),np.array(m.faces,np.uint64)));assert s.status()==mf.Error.NoError;return s
wires=[load(q)for q in r['routes']];targets=[q for q in rows if q['key']in ['OpenRB_24','OpenRB_25','OpenRB_26','OpenRB_93','OpenRB_94','OpenRB_95','current_cradle','REFERENCE current speaker_keeper','REFERENCE fixed head jaw_support']]+[q for q in mount['parts']if q['key'].startswith(('amp_roof_post','amp_screw'))];checks=[]
for q in targets:
 ob=load(q)
 for i,s in enumerate(wires):
  v=max(0,(s^ob).volume());gap=float(s.min_gap(ob,2));checks.append({'wire':i,'part':q['key'],'volumeMm3':v,'gapMmCappedAt2':gap})
 del ob;gc.collect()
checks.append({'wire':0,'part':'other_speaker_wire','volumeMm3':max(0,(wires[0]^wires[1]).volume()),'gapMmCappedAt2':float(wires[0].min_gap(wires[1],2))})
passed=not r['hits']and r['wirePairVolumeMm3']<1e-6 and all(q['volumeMm3']<1e-6 for q in checks)
rr={'passed':passed,'wholeHeadAccepted':False,'physicalFitVerified':False,'sourceHashes':{str(D/'check.json'):sha(D/'check.json'),str(am):sha(am),r['sourceManifest']:r['sourceSha256'],str(Path(__file__)):sha(__file__)},'checks':checks,'minimumIndependentGapMm':min(q['gapMmCappedAt2']for q in checks)};(D/'speaker-lines-acceptance.json').write_text(json.dumps(rr,indent=2)+'\n')
parts=[{'key':'speaker_line_'+str(i),'file':q['file'],'sha256':q['sha256'],'worldTransform':np.eye(4).tolist(),'name':q['net']+' speaker lead','color':'#d86b42'if i==0 else'#566071','net':q['net'],'wiringRole':'cable'}for i,q in enumerate(r['routes'])]
man={'integrationReady':passed,'scope':'Static illustrative speaker pair in current internal head; flexible arrangement is not a unique rigid route. Whole head closure and physical handling remain integrated acceptance.','wholeHeadAccepted':False,'additionalParts':parts,'sourceReceipt':str(D/'speaker-lines-acceptance.json'),'sourceReceiptSha256':sha(D/'speaker-lines-acceptance.json'),'routes':r['routes'],'connections':[{'id':'speaker-output-pair','name':'Amplifier to 8-ohm speaker','nets':['VO+','VO-'],'tutorial':{'prepare':['With the amplifier and speaker loose, cut the two leads with extra handling length; the drawn centerlines are approximately96mm and76mm, not required cut lengths.','Use insulation no larger than the checked1.5mm envelope where crossing between controller pins. The final2mm tinned conductor at each speaker pad is shown separately; verify marked pad polarity.'],'assemble':['Connect VO+ and VO- to the marked speaker pads and tighten the two amplifier terminal screws before mounting the amplifier.','Keep the two leads in separate layers under the controller pin rows. Route the longer positive lead outside the speaker mounting screw before returning over the keeper opening to its pad.','Mount the prewired amplifier on the detached cap before fitting controller/Pi; place the speaker cage without trapping the two leads.'],'check':['Check terminal clamping, solder insulation, polarity and gentle strain relief. Never pull on the speaker solder tabs.','Inspect wire clearance from exposed controller pins and the speaker screw head before closing. Final all-wire closure is a separate integrated check.']}}]};(D/'speaker-wiring-manifest.json').write_text(json.dumps(man,indent=2)+'\n');print(json.dumps({'passed':passed,'minGap':rr['minimumIndependentGapMm'],'near':[q for q in checks if q['gapMmCappedAt2']<.5]}))
